///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setSelectDisabled
 * @author Inswave
 * @date 2026. 09. 29
 * @param isTrue
 * @returns
 * @hidden N
*/
scwin.setSelectDisabled = function (isTrue) {
    /* sdd-asis-lifecycle:begin fn_setSelectDisabled — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('slc_uinscribeYn').setDisabled(isTrue);
    $c.util.getComponent('slc_stdYn').setDisabled(isTrue);
    $c.util.getComponent('slc_fncUlyTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_fornInvstLmtObjIsuYn').setDisabled(isTrue);
    $c.util.getComponent('slc_elwRghtTpKindCd').setDisabled(isTrue);
    $c.util.getComponent('slc_elwRghtTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_elwExerTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_autoExerTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_halfwyRedmptYn').setDisabled(isTrue);
    $c.util.getComponent('slc_elwLstSetlMethdCd').setDisabled(isTrue);
    $c.util.getComponent('slc_elwObjIdxTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_leadcomMbrNo').setDisabled(isTrue);
    $c.util.getComponent('slc_transstkAgntCd').setDisabled(isTrue);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.commaValueAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.commaValueAll = function () {
    /* sdd-asis-lifecycle:begin fn_CommaValueAll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    fn_ObjValueSetComma($c.util.getComponent('ipt_isuPrc')); //   발행가격                         
    fn_ObjValueSetComma($c.util.getComponent('ipt_isuShrs')); //   발행증권수                       
    fn_ObjValueSetComma($c.util.getComponent('ipt_isuTotSum')); //   발행총액                       
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwConvRto')); //   ELW전환비율                      
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwUlyBasPrc')); //   ELW기초자산기초가격              
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwExerPrc')); //   ELW행사가격                      
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwPrcUpPartcRt')); //   ELW가격상승참가율                
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwCompnsRt')); //   ELW보상률                        
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwFinalPayVal')); //   ELW확정지급액                    
    fn_ObjValueSetComma($c.util.getComponent('ipt_riskfreIntRt')); //   무위험이자율                     
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwDivRt')); //   ELW배당률                        
    fn_ObjValueSetComma($c.util.getComponent('ipt_applVoltRto')); //   적용변동성비율                   
    fn_ObjValueSetComma($c.util.getComponent('ipt_ordSpdRto')); //   호가스프레드                     
    fn_ObjValueSetComma($c.util.getComponent('ipt_elwKoBasPrc')); //   조기종료발생기준가격/지수
    fn_ObjValueSetComma($c.util.getComponent('ipt_isuExp')); 	  //제반비용      

    for(let i = 0 ; i < $c.util.getComponent('ipt_isuSchdlAmt').length  ; i++) {
        fn_ObjValueSetComma($c.util.getComponent('ipt_isuSchdlAmt')[i]); 
        fn_ObjValueSetComma($c.util.getComponent('ipt_isuPrfmAmt')[i]); 
    }	           
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.elwPageUsrSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elwPageUsrSearch = async function () {
    /* sdd-asis-lifecycle:begin fn_ElwPageUsrSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form.bzCd.value   = BZ_USRLST ;

    if( $c.util.getComponent('ipt_isuNm') != null ) {
        $c.util.getComponent('ipt_isuNm').setValue("");
    }

    scwin.form.action       = '/list/elwPage.do';
    scwin.form.method.value = 'elwPageSearch';
    await moveUrl('/list/elwPage.do', {});

    /* sdd-asis-lifecycle:end */
};
